   var before=a.transform.localPosition;var scale=a.transform.localScale;var group=a.GetComponent<CanvasGroup>()??a.gameObject.AddComponent<CanvasGroup>();float alpha=group.alpha;var defenderBefore=b.transform.localPosition;var defenderScale=b.transform.localScale;var defenderGroup=b.GetComponent<CanvasGroup>()??b.gameObject.AddComponent<CanvasGroup>();float defenderAlpha=defenderGroup.alpha;bool focusCaptured=false;bool done=false,captured=false,checkedHold=false,checkedImpact=false;string error=null;
