!=null&&defenderGroup.alpha==0,"Battle target proxy missing");Check(Vector3.Distance(b.transform.localPosition,defenderBefore)<.1f&&b.transform.localScale==defenderScale,"Defender gameplay transform moved");}}if(fx.ImpactEmitted){checkedImpact=true;Check(fx.VictimCount==(wallsMode?wallTargets:mode=="tie"?2:1),"Incorrect impact victim count");}}}catch(Exception e){error=e.ToString();break;}
